+fn spherical_motor_metric(ia: mat3x3<f32>, ib: mat3x3<f32>,
+    cdot: vec3<f32>, old: vec3<f32>, radius: f32) -> vec3<f32> {
+    if (radius <= 0.0) { return vec3<f32>(0.0); }
+    let raw = ia + ib;
+    // Input inertia may contain tiny upper/lower float32 asymmetry.
+    let k = 0.5 * (raw + transpose(raw));
+    let g = cdot - native_mul_mv(k, old);
+    var low = 0.0;
+    var high = length(g) / radius;
