+        let x = motor_metric_solve(shifted, -g);
+        if (dot(x,x) > radius * radius) { low = mid; }
+        else { high = mid; }
+    }
+    let shifted = k + mat3x3<f32>(vec3<f32>(high,0.0,0.0),
+        vec3<f32>(0.0,high,0.0),vec3<f32>(0.0,0.0,high));
+    let x = spherical_clamp_vector_length(motor_metric_solve(shifted,-g),radius);
+    let feasible_old = spherical_clamp_vector_length(old,radius);
+    let candidate_value = 0.5 * dot(x,native_mul_mv(k,x)) + dot(g,x);
+    let old_value = 0.5 * dot(feasible_old,native_mul_mv(k,feasible_old)) + dot(g,feasible_old);
+    // Roundoff fallback preserves a feasible non-increasing objective.
+    return select(x,feasible_old,candidate_value > old_value);
+}
